-- chair-step: inverse of read_lane_v2_b3_67_billing_capability — un-enrolls billing.capability from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'billing' and table_name = 'capability' and is_active);
select iam.apply_rls('billing', 'capability', (select token from platform.entity_types where schema_name = 'billing' and table_name = 'capability' and is_active), (select rls_variant from platform.entity_types where schema_name = 'billing' and table_name = 'capability' and is_active));
